@startuml

class Hospital {
  + Name : string
}

class ExaminationType {
  + Name : string
}

class Problem {
  + Name : string
}

class TreatmentPlan {
  + Name : string
}

class Doctor {
  + Name : string
}

class Patient {
  + Name : string
}

class Diagnosis {
  + Date : date
}

class Treatment {
  + Date : date
}

class MedicalAction {
  + Description : string
}

class Examination {
  + Date : date
}

Hospital "1" -- "*" ExaminationType : has permission for
Hospital "1" -- "*" Doctor : employs
Hospital "1" -- "*" Diagnosis : hosts
Hospital "1" -- "*" Treatment : hosts
Hospital "1" -- "*" Examination : hosts

Problem "1" -- "*" TreatmentPlan : defines
TreatmentPlan "1" -- "*" ExaminationType : advises

Doctor "1" -- "*" Diagnosis : poses
Patient "1" -- "*" Diagnosis : receives
Diagnosis "1" -- "1" Treatment : results in

Treatment "1" -- "*" MedicalAction : consists of
Treatment "1" -- "*" Examination : consists of

Examination "*" -- "1" ExaminationType : is a type of
Examination "0..1" -- "0..1" Hospital : performed at

@enduml

